# dict_diff :: ({'a': 1, 'b': 2}, {'b': 3})
def dict_diff(a, b):
    return {k: a[k] for k in a if k not in b}

if __name__ == '__main__':
    print(dict_diff(({'a': 1, 'b': 2}, {'b': 3})))

